import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFileName 是仓库阈值文件名，与包源码同目录，
// 即仓库根下的 inventory/thresholds.json。
const thresholdsFileName = "thresholds.json"

// loadThresholds 读取按仓库配置的阈值。
//
// 文件不存在或解析失败时返回 nil，调用方据此回退到 DefaultLowStockThreshold。
// 每次调用都重新读取，配置改动无需重启进程。
func loadThresholds() map[string]int {
	_, source, _, ok := runtime.Caller(0)
	if !ok {
		return nil
	}
	data, err := os.ReadFile(filepath.Join(filepath.Dir(source), thresholdsFileName))
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 优先用 inventory/thresholds.json 里该仓库的配置；
// 文件不存在或该仓库没配时回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

