package inventory

import (
	"os"
	"testing"
)

// go test 的工作目录就是包目录，与 loadThresholds 解析出的阈值文件位置一致。
const perWarehouseThresholdsPath = "thresholds.json"

// writePerWarehouseThresholdsForTest 写入阈值文件，并在测试结束后恢复原状。
func writePerWarehouseThresholdsForTest(t *testing.T, contents string) {
	t.Helper()
	previous, err := os.ReadFile(perWarehouseThresholdsPath)
	if err == nil {
		t.Cleanup(func() { _ = os.WriteFile(perWarehouseThresholdsPath, previous, 0o644) })
	} else {
		t.Cleanup(func() { _ = os.Remove(perWarehouseThresholdsPath) })
	}
	if err := os.WriteFile(perWarehouseThresholdsPath, []byte(contents), 0o644); err != nil {
		t.Fatalf("写入 %s 失败: %v", perWarehouseThresholdsPath, err)
	}
}

// removePerWarehouseThresholdsForTest 确保阈值文件不存在，并在测试结束后恢复原状。
func removePerWarehouseThresholdsForTest(t *testing.T) {
	t.Helper()
	previous, err := os.ReadFile(perWarehouseThresholdsPath)
	if err == nil {
		t.Cleanup(func() { _ = os.WriteFile(perWarehouseThresholdsPath, previous, 0o644) })
	} else {
		t.Cleanup(func() { _ = os.Remove(perWarehouseThresholdsPath) })
	}
	if err := os.Remove(perWarehouseThresholdsPath); err != nil && !os.IsNotExist(err) {
		t.Fatalf("删除 %s 失败: %v", perWarehouseThresholdsPath, err)
	}
}

func TestWarehouseThresholdFromConfigFile(t *testing.T) {
	writePerWarehouseThresholdsForTest(t, `{"shanghai": 20}`)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望配置值 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库 LowStockThreshold(chengdu) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestWarehouseThresholdMissingConfigFile(t *testing.T) {
	removePerWarehouseThresholdsForTest(t)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时 LowStockThreshold(shanghai) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestWarehouseThresholdMalformedConfigFile(t *testing.T) {
	writePerWarehouseThresholdsForTest(t, `{not json`)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件无法解析时 LowStockThreshold(shanghai) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestIsLowStockWithPerWarehouseThreshold(t *testing.T) {
	writePerWarehouseThresholdsForTest(t, `{"shanghai": 20}`)

	if !IsLowStock("shanghai", 19) {
		t.Fatal("19 < 配置阈值 20，应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于配置阈值不算低库存（严格小于）")
	}
	if !IsLowStock("chengdu", DefaultLowStockThreshold-1) {
		t.Fatal("未配置仓库应当沿用默认阈值")
	}
}

func TestLowStockWarehousesWithPerWarehouseThresholds(t *testing.T) {
	writePerWarehouseThresholdsForTest(t, `{"shanghai": 20}`)

	got := LowStockWarehouses(map[string]int{
		"shanghai": 15, // 15 < 20：按配置阈值算低
		"chengdu":  1,  // 1 < 5：按默认阈值算低
		"wuhan":    99, // 不低
		"xian":     5,  // 等于默认阈值：不低
	})
	want := []string{"chengdu", "shanghai"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
		}
	}
}
